import {test,expect} from 'vitest';
import {toDisplayLngLat,fromDisplayLngLat,publicGeometryDigest,withinExtent} from '../src/map-binding';
import {legalKnowledge} from './fixtures/legal-knowledge';

// Independent values frozen by the design author, not generated by the subject.
const controls=[
  [[0,0],[0,0]],[[400,0],[0.003593261136,0]],
  [[0,300],[0,-0.002694945851]],[[400,300],[0.003593261136,-0.002694945851]],
  [[200,150],[0.001796630568,-0.001347472926]],
] as const;
test('MA02 synthetic axes and all five frozen geographic control values agree independently',()=>{
  for(const [point,ll] of controls){
    const actual=toDisplayLngLat(point);
    expect(actual[0]).toBeCloseTo(ll[0],11);expect(actual[1]).toBeCloseTo(ll[1],11);
    const restored=fromDisplayLngLat(ll);
    expect(Math.hypot(restored[0]-point[0],restored[1]-point[1])).toBeLessThanOrEqual(0.1);
    const roundTrip=fromDisplayLngLat(actual);
    expect(Math.hypot(roundTrip[0]-point[0],roundTrip[1]-point[1])).toBeLessThanOrEqual(0.1);
  }
  expect(toDisplayLngLat([170,150])[0]-toDisplayLngLat([50,150])[0]).toBeCloseTo(0.001077978341,11);
  expect(toDisplayLngLat([110,150])[0]-toDisplayLngLat([50,150])[0]).toBeCloseTo(0.000538989170,11);
});
test('MA02 nonfinite and unsuitable latitude never produce display coordinates',()=>{
  expect(()=>toDisplayLngLat([NaN,1])).toThrow();
  expect(()=>fromDisplayLngLat([0,90])).toThrow();
  expect(withinExtent([-100,150],[0,0,400,300])).toBe(false);
  expect(withinExtent([-100,150],[-200,-150,600,450])).toBe(true);
});
test('MA03 geometry digest binds only canonical legal geometry and rejects expanded or nonfinite domains',async()=>{
  const geometry=legalKnowledge.geometry;
  const first=await publicGeometryDigest(geometry);
  expect(first).toMatch(/^[a-f0-9]{64}$/);
  expect(await publicGeometryDigest({...geometry})).toBe(first);
  expect(await publicGeometryDigest({...geometry,N:[110,150]})).not.toBe(first);
  await expect(publicGeometryDigest({...geometry,extent:[800,600]})).rejects.toThrow();
  await expect(publicGeometryDigest({...geometry,H:[NaN,150]})).rejects.toThrow();
  await expect(publicGeometryDigest({...geometry,rough:[200,0,500,300]})).rejects.toThrow();
  await expect(publicGeometryDigest({...geometry,corridor_width:-20})).rejects.toThrow();
});
